q.push(new A.F("cr_bequeath",10,"\u041d\u0430\u0441\u043b\u0435\u0434\u0438\u0435 \u043a\u043e\u043d\u0435\u0447\u043d\u043e\u0441\u0442\u0438","\u0420\u0430\u0437 \u0432 \u0434\u043b\u0438\u043d\u043d\u044b\u0439 \u043e\u0442\u0434\u044b\u0445 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0435\u043c \u0432\u0436\u0438\u0432\u043b\u044f\u0435\u0442\u0435 \u0441\u0443\u0449\u0435\u0441\u0442\u0432\u0443 \u0441\u0435\u043c\u044f \u0411\u0430\u0433\u0440\u044f\u043d\u0446\u0430: \u0437\u0430 1 \u043c\u0438\u043d\u0443\u0442\u0443 \u043e\u043d\u043e \u043e\u0442\u0440\u0430\u0449\u0438\u0432\u0430\u0435\u0442 \u0443\u0442\u0440\u0430\u0447\u0435\u043d\u043d\u044b\u0435 \u043a\u043e\u043d\u0435\u0447\u043d\u043e\u0441\u0442\u0438 \u0438 \u043e\u0440\u0433\u0430\u043d\u044b, \u0432\u043e\u0441\u0441\u0442\u0430\u043d\u0430\u0432\u043b\u0438\u0432\u0430\u0435\u0442 2\u043a8 + \u0443\u0440\u043e\u0432\u0435\u043d\u044c \u0434\u0440\u0443\u0438\u0434\u0430 \u0445\u0438\u0442\u043e\u0432, \u0430 \u043e\u0434\u043d\u0430 \u0431\u043e\u043b\u0435\u0437\u043d\u044c \u0438\u043b\u0438 \u043e\u0442\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u0435 \u043d\u0430 \u043d\u0451\u043c \u0437\u0430\u043a\u0430\u043d\u0447\u0438\u0432\u0430\u0435\u0442\u0441\u044f.",!0))
